def transform(grid):
    h, w = len(grid), len(grid[0])
    strip = set()
    palette = None

    # Find the three repeated rows or columns encoding the color sequence.
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            cols = [c for c in range(w) if grid[r][c] != 0]
            if len(cols) >= 2:
                palette = [grid[r][c] for c in cols]
                strip = {(rr, c) for rr in (r, r + 1, r + 2) for c in cols}
                break

    if palette is None:
        for c in range(w - 2):
            vals = [[grid[r][cc] for cc in (c, c + 1, c + 2)] for r in range(h)]
            if all(row[0] == row[1] == row[2] for row in vals):
                rows = [r for r in range(h) if grid[r][c] != 0]
                if len(rows) >= 2:
                    palette = [grid[r][c] for r in rows]
                    strip = {(r, cc) for r in rows for cc in (c, c + 1, c + 2)}
