    for r in range(h):
        for c in range(w):
            if (r, c) not in strip and grid[r][c] != 0:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    source_color = max(counts, key=counts.get)
    shape = [(r, c) for r in range(h) for c in range(w)
             if (r, c) not in strip and grid[r][c] == source_color]
    min_r = min(r for r, c in shape)
    max_r = max(r for r, c in shape)
    min_c = min(c for r, c in shape)
    height = max_r - min_r + 1

    # Preserve the vertical position of the existing shape matching its color.
    source_index = palette.index(source_color) if source_color in palette else 0
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        dr = min_r + (i - source_index) * height - min_r
        for r, c in shape:
            rr = r + dr
            if 0 <= rr < h:
                out[rr][c] = color
    return out
